# Auto-generated by LeetCode Agent

class Solution:
    def sumOfSquares(self, nums: List[int]) -> int:
        total_sum = 0
        array_length = len(nums)
        
        for index in range(array_length):
            if array_length % (index + 1) == 0:
                total_sum += nums[index] ** 2
                
        return total_sum